SELECT c.relrowsecurity AND NOT c.relforcerowsecurity AS enabled_expected_force,(SELECT count(*)=1 FROM pg_policy p WHERE p.polrelid=c.oid) AS exactly_one_policy,(SELECT count(*)=1 FROM pg_policy p WHERE p.polrelid=c.oid AND p.polname='training_sessions_athlete_select' AND p.polcmd='r' AND p.polroles=ARRAY['authenticated'::regrole::oid] AND p.polwithcheck IS NULL) AS exact_owner_select_policy, (SELECT pg_get_expr(p.polqual,p.polrelid) FROM pg_policy p WHERE p.polrelid=c.oid AND p.polname='training_sessions_athlete_select') AS inspect_exact_owner_and_athlete_predicate FROM pg_class c WHERE c.oid='public.training_sessions'::regclass;
